using System;
using System.IO;
using System.Linq;
using Touchfish;
public static partial class RuleTests {
 static void Dragons(){
  var all=catalog.Deckable(catalog.Pool("classic-2014"));Check(all.Count==382&&all.All(matchRules.Supports),"All 382 classic collectible cards supported");
  var g=MatchFixture();long now=1000;g.ClockNowMs=()=>now;Check(!g.TurnClockEnabled&&g.TurnClockRemainingMs==-1,"No Nozdormu means unlimited turn");now+=60000;Check(!g.TryEndTimedTurn()&&g.Turn==1,"Unlimited turn does not automatically end");var noz=g.Summon(0,"VAN_EX1_560");Check(g.TurnClockEnabled&&g.TurnClockRemainingMs==15000,"Nozdormu starts fifteen seconds");now+=4000;int sequence=g.TurnClockSequence;g.Emote(0,HeroEmotes.Options("MAGE")[0].Value);Check(g.TurnClockRemainingMs==11000&&g.TurnClockSequence==sequence,"Emote cannot reset clock");g.Summon(1,"VAN_EX1_560");Check(g.TurnClockRemainingMs==11000,"Second Nozdormu does not reset countdown");g.Silence(new MatchTarget(0,noz.Id));Check(g.TurnClockEnabled&&g.TurnClockRemainingMs==11000,"One active source keeps timer running");var other=g.Players[1].Board.Single();g.Silence(new MatchTarget(1,other.Id));Check(!g.TurnClockEnabled&&g.TurnClockRemainingMs==-1,"Silencing last source restores unlimited");g.Summon(0,"VAN_EX1_560");Check(g.TurnClockRemainingMs==15000,"New live source starts a fresh timer");now+=15000;int fire=Hand(g,"CS2_029");Check(!g.Play(0,fire,new MatchTarget(1)).Success&&g.Players[0].Mana==10&&g.Players[0].Hand.Any(h=>h.Id==fire),"Late play rejected before resources consumed");Check(g.TryEndTimedTurn()&&g.Active==1&&g.Turn==2&&g.TurnClockRemainingMs==15000,"Timeout ends turn and grants opponent a new clock");Check(!g.TryEndTimedTurn()&&g.Log.Count(x=>x.Contains("倒计时结束"))==1,"Poll does not repeat the same timeout");
  g=MatchFixture();now=0;g.ClockNowMs=()=>now;noz=g.Summon(0,"VAN_EX1_560");noz.DamageTaken=noz.MaxHealth;g.Cleanup();Check(!g.TurnClockEnabled,"Dead Nozdormu stops clock");noz=g.Summon(0,"VAN_EX1_560");g.Transform(new MatchTarget(0,noz.Id),"VAN_CS2_182");Check(!g.TurnClockEnabled,"Transformation stops intrinsic clock");noz=g.Summon(1,"VAN_EX1_560");g.Play(0,Hand(g,"EX1_564"),new MatchTarget(1,noz.Id));g.Silence(new MatchTarget(1,noz.Id));Check(g.TurnClockEnabled,"Faceless copy is also a clock source");g.ReturnToHand(new MatchTarget(0,g.Players[0].Board.Single(u=>u.CardId=="VAN_EX1_560").Id));Check(!g.TurnClockEnabled,"Returning last copy to hand removes timer");
  g=MatchFixture();g.Players[0].MulliganDone=false;now=0;g.ClockNowMs=()=>now;g.Summon(0,"VAN_EX1_560");Check(!g.TurnClockEnabled,"Mulligan never has countdown");g.Players[0].MulliganDone=true;Check(g.TurnClockRemainingMs==15000,"Clock begins after opening is complete");
  var host=new LanHostGame(catalog,matchRules.TrainingDeck("MAGE"),matchRules.TrainingDeck("WARRIOR"),42,0);g=host.Game;g.MarkMulliganCompleteForTests();foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=p.MaxMana=10;}now=0;g.ClockNowMs=()=>now;g.Summon(1,"VAN_EX1_560");var snapshot=LanProtocol.View(g,1,"clock",0);Check(snapshot.TurnClockRemainingMs==15000&&snapshot.TurnClockSequence>0,"Host snapshots clock explicitly");var view=LanProtocol.ReadView(catalog,LanProtocol.Copy(snapshot));Check(view.TurnClockEnabled&&view.TurnClockRemainingMs<=15000&&!view.TryEndTimedTurn(),"Replica displays timer but never decides timeout");snapshot.TurnClockRemainingMs=15001;bool invalid=false;try{LanProtocol.ReadView(catalog,snapshot);}catch(InvalidDataException){invalid=true;}Check(invalid,"Malformed clock rejected");now=15000;fire=Hand(g,"CS2_029");var result=host.Execute(0,new LanCommand{Kind="play",Source=fire,Target=new MatchTarget(1),Revision=0,Session=host.Session});Check(!result.Success&&host.Revision==1&&g.Active==1&&g.Players[1].Health==30&&g.Players[0].Hand.Any(h=>h.Id==fire),"Host expiry wins race with a late client command");Check(!host.PollTimeout()&&host.Revision==1,"Authority revision changes once per timed turn");
  g=MatchFixture();now=0;g.ClockNowMs=()=>now;g.Summon(0,"VAN_EX1_560");g.EntranceAnimationsEnabled=true;g.StartEntranceWait();now=15000;Check(!g.TryEndTimedTurn()&&g.Active==0,"Existing shared animation wait remains enforced");g.LimitAnimationWait(0);Check(g.TryEndTimedTurn()&&g.Active==1,"Expired turn ends immediately once animation wait finishes");
  g=MatchFixture();g.Players[0].Health=5;g.Players[0].Armor=9;var ward=g.Summon(0,"VAN_EX1_001");g.Play(0,Hand(g,"EX1_561"),new MatchTarget(0));Check(g.Players[0].Health==15&&g.Players[0].Armor==9&&g.HeroHealthLimit(0)==30,"Alexstrasza sets friendly current health without changing armor or maximum");Check(g.AttackValue(ward)==1&&!g.VisualEvents.Any(v=>v.Kind=="damage"),"Health setting is neither healing nor damage");g=MatchFixture();g.Players[1].Armor=7;g.Play(0,Hand(g,"EX1_561"),new MatchTarget(1));Check(g.Players[1].Health==15&&g.Players[1].Armor==7,"Alexstrasza sets enemy health through armor");g=MatchFixture();var target=g.Summon(1,"VAN_CS2_182");int dragon=Hand(g,"EX1_561");Check(!g.Play(0,dragon,new MatchTarget(1,target.Id)).Success&&g.Players[0].Mana==10&&g.Players[0].Hand.Count==1,"Alexstrasza minion target rejected atomically");g=MatchFixture();g.ReplaceHero(1,HeroReplacementRules.JaraxxusId);g.Players[1].Health=2;g.Play(0,Hand(g,"EX1_561"),new MatchTarget(1));Check(g.Players[1].Health==15&&g.HeroHealthLimit(1)==15&&g.Players[1].HeroFormId==HeroReplacementRules.JaraxxusId,"Alexstrasza preserves replaced hero identity and max health");
  g=MatchFixture();var extension=new CardRecord{Id="test:clock-alias",BaseId="EX1_560",EffectId="test:unrelated-clock@1",SetId="test",Type="MINION",CardClass="NEUTRAL",Attack=1,Health=1,Mechanics=new string[0]};catalog.Cards.Add(extension.Id,extension);try{g.Rules.RegisterExtension(extension.EffectId,"NONE",c=>{});g.Summon(0,extension.Id);Check(!g.TurnClockEnabled,"Namespaced extension with same base ID does not inherit Classic clock");}finally{catalog.Cards.Remove(extension.Id);}
  JsonData.Write(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../../previews/match-rule-coverage.json"),new{SupportedCards=all.Count(matchRules.Supports),TotalCards=all.Count,Cards=all.Select(c=>new{c.Id,c.Name,Supported=matchRules.Supports(c)}).ToArray(),Scope="All 382 classic cards supported"});
 }
}
